#include <unistd.h>
#include <stdint.h>

int read_socket_data(int s, void* arg, int* len) {
    // Read the header to determine the length of the incoming data
    uint32_t data_length = 0;
    ssize_t bytes_read = read(s, &data_length, sizeof(data_length));

    // Check if reading the header failed
    if (bytes_read != sizeof(data_length)) {
        return -1;
    }

    // Ensure the data length is valid (non-negative and not overflow)
    if (data_length > INT32_MAX || data_length < 0) {
        return -1;
    }

    // Convert the data length to a signed integer
    int data_length_int = (int)data_length;

    // If the data length is zero, no need to read further
    if (data_length_int == 0) {
        *len = 0;
        return 0; // Assuming type 0 for zero-length data
    }

    // Ensure the data length does not exceed the buffer capacity
    if (data_length_int > *len) {
        return -1; // Cannot read more data than the buffer can hold
    }

    // Read the actual data into the buffer
    bytes_read = read(s, arg, data_length_int);

    // Check if reading the data failed
    if (bytes_read != data_length_int) {
        return -1;
    }

    // Update the provided length with the actual length of the data read
    *len = data_length_int;

    // Return the type of the data read (assuming type 1 for this example)
    return 1;
}
